// --- useDarkMode ---
// What it does: Custom theme preference hook synchronizing dark mode across document elements and storage.
// Why it's structured this way: Preserves consistent dark/light visual states for medical data legibility.
// Parameters & Returns: None. Returns [darkMode, setDarkMode] tuple.
// ------------------------------------------------------------------------------
function useDarkMode() {
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window === "undefined") return false;

    const saved = localStorage.getItem("medicare-theme");
    if (saved === "dark") return true;
    if (saved === "light") return false;

    return window.matchMedia?.("(prefers-color-scheme: dark)").matches ?? false;
  });

  useEffect(() => {
    localStorage.setItem("medicare-theme", darkMode ? "dark" : "light");
    document.documentElement.classList.toggle("dark", darkMode);
    document.documentElement.style.colorScheme = darkMode ? "dark" : "light";
    document.body.style.background = darkMode ? "#0b1413" : "#f8faf9";
  }, [darkMode]);

  return [darkMode, setDarkMode];
}

