// --- RiskBadge ---
// What it does: Renders normalized risk severity pill badge (Low, Moderate, High).
// Why it's structured this way: Colors triage categories to immediately communicate risk urgency.
// Parameters & Returns: Props: level (string), darkMode (boolean). Returns styled span JSX.
// ------------------------------------------------------------------------------
function RiskBadge({ level, darkMode }) {
  const classes =
    level === "Low"
      ? darkMode
        ? "bg-emerald-500/10 text-emerald-400"
        : "bg-emerald-50 text-emerald-700"
      : level === "Moderate"
        ? darkMode
          ? "bg-amber-500/10 text-amber-400"
          : "bg-amber-50 text-amber-700"
        : darkMode
          ? "bg-red-500/10 text-red-400"
          : "bg-red-50 text-red-600";

  return (
    <span className={`rounded-full px-2.5 py-1 text-[8px] font-medium ${classes}`}>
      {level} risk
    </span>
  );
}

