// --- TrendChart ---
// What it does: SVG line chart depicting historical disease risk probability progression over time.
// Why it's structured this way: Maps chronological risk data points to responsive SVG polyline without external chart bundle overhead.
// Parameters & Returns: Props: darkMode (boolean), data (array). Returns SVG line chart JSX.
// ------------------------------------------------------------------------------
function TrendChart({ darkMode, data = [] }) {
  if (!data || data.length === 0) {
    return (
      <div className="flex h-[190px] w-full flex-col items-center justify-center p-4 text-center">
        <TrendingUp size={24} className="text-slate-400 opacity-40 mb-1" />
        <p className={`text-[11px] font-medium ${darkMode ? "text-slate-300" : "text-slate-600"}`}>
          No risk trend history recorded
        </p>
        <p className={`text-[9px] mt-0.5 ${darkMode ? "text-slate-500" : "text-slate-400"}`}>
          Generated disease predictions will track your historical risk progression here.
        </p>
      </div>
    );
  }

  const width = 520;
  const height = 170;
  const paddingLeft = 34;
  const paddingRight = 8;
  const paddingTop = 12;
  const paddingBottom = 28;

  const min = 0;
  const max = 100;

  const points = data.map((item, index) => {
    const x =
      paddingLeft +
      (data.length > 1
        ? (index / (data.length - 1)) * (width - paddingLeft - paddingRight)
        : (width - paddingLeft - paddingRight) / 2);

    const y =
      height -
      paddingBottom -
      ((item.score - min) / (max - min)) *
        (height - paddingTop - paddingBottom);

    return {
      ...item,
      x,
      y,
    };
  });

  const polyline = points.map((point) => `${point.x},${point.y}`).join(" ");

  return (
    <div className="mt-3 h-[190px] w-full">
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
      >
        {[20, 40, 60, 80, 100].map((tick) => {
          const y =
            height -
            paddingBottom -
            ((tick - min) / (max - min)) *
              (height - paddingTop - paddingBottom);

          return (
            <g key={tick}>
              <line
                x1={paddingLeft}
                y1={y}
                x2={width - paddingRight}
                y2={y}
                stroke={darkMode ? "#263936" : "#e5e7eb"}
                strokeDasharray="3 4"
              />
              <text
                x="5"
                y={y + 3}
                fontSize="9"
                fill={darkMode ? "#64748b" : "#94a3b8"}
              >
                {tick}%
              </text>
            </g>
          );
        })}

        {data.map((item, index) => {
          const point = points[index];

          return (
            <text
              key={`${item.month}-${index}`}
              x={point.x}
              y={height - 8}
              textAnchor="middle"
              fontSize="9"
              fill={darkMode ? "#64748b" : "#94a3b8"}
            >
              {item.month}
            </text>
          );
        })}

        <polyline
          points={polyline}
          fill="none"
          stroke="#20b480"
          strokeWidth="3"
          strokeLinecap="round"
          strokeLinejoin="round"
        />

        {points.map((point, index) => (
          <circle
            key={`pt-${index}`}
            cx={point.x}
            cy={point.y}
            r="4"
            fill={darkMode ? "#15211f" : "#ffffff"}
            stroke="#20b480"
            strokeWidth="2"
          />
        ))}
      </svg>
    </div>
  );
}

